import {stages,steps,legacyGroups} from './data.js';
import {normalize,browse,complete} from './state.js';
const $=id=>document.getElementById(id),key='wufang-sop-v2';
let state=normalize(null,steps.length),saveOK=true;
try{const saved=localStorage.getItem(key);if(saved){state=normalize(JSON.parse(saved),steps.length)}else{const old=JSON.parse(localStorage.getItem('wufang-sop-v1'));if(old){state=normalize({view:Math.max(0,legacyGroups.findIndex(g=>g.includes(old.view))),done:legacyGroups.flatMap((g,i)=>g.every(n=>old.done?.includes(n))?[i]:[])},steps.length)}}}catch{saveOK=false}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));saveOK=true}catch{saveOK=false}render()}
function render(){const s=steps[state.view],done=state.done.includes(s.id),all=state.done.length===steps.length;
$('count').textContent=`${state.done.length} / ${steps.length}`;$('progress').max=steps.length;$('progress').value=state.done.length;$('progress').setAttribute('aria-label','已完成步骤');
$('stages').replaceChildren(...stages.map((name,i)=>{const b=document.createElement('button');b.textContent=`${String(i+1).padStart(2,'0')} ${name}`;b.className=i===s.stage?'active':steps.filter(x=>x.stage===i).every(x=>state.done.includes(x.id))?'done':'';b.setAttribute('aria-current',i===s.stage?'step':'false');b.onclick=()=>{state=browse(state,steps.findIndex(x=>x.stage===i),steps.length);persist()};return b}));
$('phase').textContent=`${stages[s.stage]} / ${s.stage<2?'活动准备':s.stage===7?'收尾':'五城风味'}`;$('number').textContent=`环节 ${String(s.id+1).padStart(2,'0')} / ${steps.length}`;$('context').textContent=s.context;$('title').textContent=s.title;
for(const type of ['flow','food']){const list=$(type);list.replaceChildren();let lastWhen='';for(const item of s[type]){if(item.when&&item.when!==lastWhen){const group=document.createElement('li');group.className='timing';group.textContent=item.when;list.append(group);lastWhen=item.when}const li=document.createElement('li');li.className=(item.owner==='JW'?'jw':item.owner==='LZ'?'lz':'shared')+(item.when==='上虾饺前'?' urgent':'');const badge=document.createElement('span');badge.className='owner';badge.textContent=item.owner==='共同'?'两人共同':item.owner;const text=document.createElement('span');text.textContent=item.text;li.append(badge,text);list.append(li)}if(!s[type].length){const li=document.createElement('li');li.className='empty';li.textContent='本环节无额外餐饮任务';list.append(li)}}
$('status').textContent=all?'✓ 本场全部环节已完成':done?'✓ 此环节已完成':'○ 此环节待完成';$('undo').hidden=!done;$('prev').disabled=s.id===0;$('next').disabled=s.id===steps.length-1;$('complete').disabled=done;$('complete').innerHTML=done?'✓ 此环节已完成<small>Completed</small>':'✓ 标记完成并继续<small>Mark Complete</small>';
$('upnext').textContent=steps[s.id+1]?.title||(all?'本场流程已完成，辛苦了！':'最后环节 · 完成后可返回查看遗漏环节');$('current').disabled=all;
$('save').textContent=saveOK?'进度保存在这台设备 · 前后浏览不会标记完成':'无法保存进度，请勿关闭或刷新此页面';}
$('prev').onclick=()=>{state=browse(state,state.view-1,steps.length);persist()};$('next').onclick=()=>{state=browse(state,state.view+1,steps.length);persist()};$('complete').onclick=()=>{state=complete(state,steps.length);persist()};$('current').onclick=()=>{const i=steps.findIndex(x=>!state.done.includes(x.id));if(i>=0){state.view=i;persist()}};$('undo').onclick=()=>{state.done=state.done.filter(i=>i!==state.view);persist()};$('reset').onclick=()=>$('resetDialog').showModal();$('resetDialog').addEventListener('close',()=>{if($('resetDialog').returnValue==='reset'){state=normalize(null,steps.length);persist()}});window.addEventListener('storage',e=>{if(e.key===key){try{state=normalize(JSON.parse(e.newValue),steps.length);render()}catch{}}});render();
